import{app,BrowserWindow,WebContentsView}from'electron';import{mkdtemp,writeFile}from'node:fs/promises';import{resolve,join}from'node:path';import assert from'node:assert/strict';import{attachPlaywrightView}from'../../packages/browser/src/playwright-view.js';import{UniversalFormSession}from'../../packages/browser/src/universal-form.js';
const dir=await mkdtemp(resolve('.backups/universal-engine-smoke-'));app.setPath('userData',dir);await app.whenReady();const window=new BrowserWindow({show:false});const view=new WebContentsView({webPreferences:{partition:'offerflash-universal-actions',sandbox:true,contextIsolation:true,nodeIntegration:false,backgroundThrottling:false}});window.contentView.addChildView(view);view.setBounds({x:0,y:0,width:1000,height:800});
const profile:any={version:1,updatedAt:'',fullName:'虚构候选人',fullNameEn:'Fictional Candidate',email:'fixture@example.invalid',phone:'2025550100',school:'虚构大学',schoolEn:'',degree:'硕士',major:'计算机',majorEn:'',graduationMonth:'2027-06',skills:[],cities:[],targetRoles:[],resumeText:'',career:{schemaVersion:1,sources:[],primaryEducationId:'edu',educations:[{id:'edu',school:'虚构大学',schoolEn:'',major:'计算机',majorEn:'',degree:'硕士',startDate:'2025-09',endDate:'2027-06',description:'',confirmation:'confirmed',revision:1,confirmedRevision:1,confirmedAt:'2026-10-01'}],internships:[],projects:['一','二'].map((n,i)=>({id:'p'+i,name:'虚构项目'+n,role:'开发者',description:'原创虚构描述'+n,startDate:'2025-01',endDate:'2025-06',ongoing:false,url:'',confirmation:'confirmed',revision:1,confirmedRevision:1,confirmedAt:'2026-10-01'})),publications:[]}};
const html=`<form onsubmit="window.submits++;return false"><label>姓名<input id="n"></label><label>邮箱<input id="e" type="email"></label><label>手机号<input value="KEEP" id="p"></label><fieldset><legend>教育经历</legend><label>学校名称<input id="s"></label><label>开始时间<input type="month" id="start"></label><button type="button" role="combobox" aria-label="学历" aria-valuetext="" id="degree" onclick="document.querySelector('#menu').hidden=false">请选择</button><div id="menu" role="listbox" hidden><div role="option" onclick="document.querySelector('#degree').setAttribute('aria-valuetext','硕士');this.parentElement.hidden=true">硕士</div><div role="option">本科</div></div></fieldset><fieldset class="project"><legend>项目经历</legend><label>项目名称<input></label><label>职务<input></label></fieldset><button type="button" onclick="const g=document.querySelector('.project').cloneNode(true);g.querySelectorAll('input').forEach(e=>e.value='');this.before(g)">添加项目经历</button><button id="submit">提交申请</button><input type="checkbox" aria-label="同意隐私协议"></form><script>window.submits=0</script>`;
try{await view.webContents.loadURL('data:text/html;charset=utf-8,'+encodeURIComponent(html));const attached=await attachPlaywrightView(view.webContents);const abort=new AbortController(),session=new UniversalFormSession(attached.page,profile,async()=>profile,()=>1,abort.signal,false);let x:any=await session.inspect();let checks=0;const fact=(kind:string,record='contact')=>session.facts.find(f=>f.kind===kind&&f.record===record)!.ref;
const fill=async(label:string,kind:string,record='contact',action:any='fill')=>{x=await session.inspect();const field=x.fields.find((f:any)=>f.label===label&&f.candidates.includes(fact(kind,record)));assert.ok(field,label);const r=await session.act({observation:x.observation,action,target:field.ref,fact:fact(kind,record)});assert.equal(r.verified,true);checks++;};
await fill('姓名','fullName');await assert.rejects(session.act({observation:x.observation,action:'fill',target:'field-0',fact:fact('fullName')}),/FRESH/);checks++;
await fill('邮箱','email');await fill('学校名称','school','education-1');await fill('开始时间','startDate','education-1');
x=await session.inspect();let degree=x.fields.find((f:any)=>f.label==='学历');await session.act({observation:x.observation,action:'open',target:degree.ref});x=await session.inspect();await session.act({observation:x.observation,action:'choose',target:x.options.find((o:any)=>o.label==='硕士').ref,fact:fact('degree','education-1')});checks++;
await fill('项目名称','name','project-1');await fill('职务','role','project-1');x=await session.inspect();await session.act({observation:x.observation,action:'add',target:x.actions[0].ref});checks++;
await fill('项目名称','name','project-2');await fill('职务','role','project-2');const final=await session.verify();assert.equal(final.verified,9);assert.equal(await attached.page.locator('#p').inputValue(),'KEEP');assert.equal(await attached.page.locator('[type=checkbox]').isChecked(),false);assert.equal(await attached.page.evaluate('window.submits'),0);checks+=4;
x=await session.inspect();await assert.rejects(session.act({observation:x.observation,action:'add',target:'add-0'}),/NO_ADDITIONAL/);checks++;
abort.abort();await assert.rejects(session.inspect(),/CONTEXT_CHANGED/);checks++;await attached.close();assert.equal(view.webContents.isDestroyed(),false);checks++;console.log(JSON.stringify({universalSmoke:true,ok:true,checks,verified:final.verified,paidRequests:0}));await writeFile(join(dir,'result.json'),JSON.stringify({ok:true,checks,final},null,2));view.webContents.close();window.destroy();app.exit(0);}catch(e){console.error(e);window.destroy();app.exit(1);}
